  insert into actualites (titre, contenu, epinglee, course_id, cree_par, publiee_le) values ('Reprise des entraînements le 24 août', 'Le planning de la semaine est publié dans l''onglet Entraînement, et le sera chaque dimanche soir. Natation le lundi et le jeudi, piste le mardi, vélo le mercredi et le samedi.', false, null, '9d3b1772-b18c-5f10-90c6-9a0161bc9d02', ((d0 + -4) + time '21:15:00'));
  insert into actualites (titre, contenu, epinglee, course_id, cree_par, publiee_le) values ('Doussard : les inscriptions ferment le 30 août', 'C''est notre course club de la rentrée, on vise une équipe complète. Déclarez-vous dans le calendrier, même en « intéressé » si vous n''êtes pas sûr : ça nous permet de savoir sur qui compter.', false, '19d635ce-1b1e-56b1-b866-e95dc9d76bd9', 'a188f243-db35-5472-adeb-6bda3154d7f8', ((d0 + -1) + time '08:40:00'));
